<?php require_login(['admin','teacher']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO notices(title,body,audience) VALUES(?,?,?)');$s->execute([trim($_POST['title']),trim($_POST['body']),$_POST['audience']]);flash('success','Notice published.');redirect('index.php?page=notices');}if(isset($_GET['delete'])&&user()['role']==='admin'){$pdo->prepare('DELETE FROM notices WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Notice deleted.');redirect('index.php?page=notices');}$rows=$pdo->query('SELECT * FROM notices ORDER BY id DESC')->fetchAll();?><div class="grid2"><section class="panel"><h2>Publish Notice</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Title<input required name="title"></label><label>Audience<select name="audience"><option>all</option><option>students</option><option>parents</option><option>teachers</option></select></label><label class="wide">Message<textarea required name="body" rows="7"></textarea></label><button class="btn primary wide">Publish Notice</button></form></section><section class="panel"><h2>Published Notices</h2><?php foreach($rows as $r):?><article class="notice"><div><span class="badge"><?=e($r['audience'])?></span> <small><?=e(date('d M Y',strtotime($r['published_at'])))?></small></div><h3><?=e($r['title'])?></h3><p><?=nl2br(e($r['body']))?></p><?php if(user()['role']==='admin'):?><a class="action danger-text" data-confirm="Delete notice?" href="index.php?page=notices&delete=<?=$r['id']?>">Delete</a><?php endif;?></article><?php endforeach;?></section></div>
